    line-height: 1.428;\r\n    color: $gray-700;\r\n\r\n    @include media-breakpoint-up(md) { padding: 10px 20px; }\r\n\r\n    @include hover-focus() {\r\n      background-color: rgba(#fff, .5);\r\n      color: $gray-900;\r\n    }\r\n\r\n    + .nav-link { margin-left: 3px; }\r\n\r\n    &.active {\r\n      background-color: #fff;\r\n      color: $gray-900;\r\n      font-weight: 500;\r\n      letter-spacing: -.1px;\r\n    }\r\n  }\r\n}\r\n","/* ###### 3.11 Pagination ###### */\r\n\r\n.page-item {\r\n  &:first-child .page-link,\r\n  &:last-child .page-link { border-radius: 0; }\r\n\r\n  + .page-item { margin-left: 1px; }\r\n\r\n  &.active .page-link { background-color: $az-color-primary; }\r\n}\r\n\r\n.page-link {\r\n  color: $gray-700;\r\n  padding: 0;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 36px;\r\n  height: $az-height-base;\r\n  border-width: 0;\r\n  background-color: $gray-200;\r\n  margin-left: 0;\r\n  font-weight: 500;\r\n\r\n  i {\r\n    font-size: 18px;\r\n    line-height: 0;\r\n  }\r\n\r\n  @include hover-focus() {\r\n    color: $gray-900;\r\n    background-color: $gray-300;\r\n  }\r\n}\r\n\r\n.pagination-dark {\r\n  .page-item.active {\r\n    .page-link {\r\n      background-color: $az-color-primary;\r\n      color: #fff;\r\n    }\r\n  }\r\n\r\n  .page-link {\r\n    font-weight: 400;\r\n    background-color: rgba(#fff, .05);\r\n    color: rgba(#fff, .8);\r\n\r\n    @include hover-focus() {\r\n      color: #fff;\r\n      background-color: rgba(#fff, .08);\r\n    }\r\n  }\r\n}\r\n\r\n.pagination-primary {\r\n  .page-item.active .page-link {\r\n    background-color: $blue;\r\n  }\r\n}\r\n\r\n.pagination-success {\r\n  .page-item.active .page-link {\r\n    background-color: $green;\r\n  }\r\n}\r\n\r\n.pagination-circled {\r\n  .page-item {\r\n    + .page-item { margin-left: 5px; }\r\n\r\n    &:first-child,\r\n    &:last-child {\r\n      .page-link { @include border-radius(100%); }\r\n    }\r\n  }\r\n\r\n  .page-link {\r\n    padding: 0;\r\n    width: 40px;\r\n    @include border-radius(100%);\r\n  }\r\n}\r\n","\r\n/* ###### 3.12 Popover ###### */\r\n\r\n.popover {\r\n  font-size: 12px;\r\n  padding: 0;\r\n  @include border-radius(0);\r\n}\r\n\r\n.popover-header {\r\n  text-transform: uppercase;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: $gray-800;\r\n  letter-spacing: 0.5px;\r\n  padding: 12px 15px;\r\n  background-color: #fff;\r\n  border-color: $az-border-color;\r\n  @include border-top-radius(0);\r\n\r\n  &::before { display: none !important; }\r\n}\r\n\r\n.popover-body {\r\n  padding: 15px;\r\n\r\n  p:last-child { margin-bottom: 0;}\r\n}\r\n\r\n// colored head\r\n.popover-head-primary { @include popover-head-variant($az-color-primary); }\r\n.popover-head-secondary { @include popover-head-variant($az-color-secondary); }\r\n\r\n.popover-head-primary,\r\n.popover-head-secondary {\r\n  &,.popover-header { border: 0; }\r\n\r\n  .popover-body {\r\n    border: 1px solid $az-border-color;\r\n    border-top-width: 0;\r\n    @include border-bottom-radius(2px);\r\n  }\r\n\r\n  &.bs-popover-bottom,\r\n  &.bs-popover-auto[x-placement^=\"bottom\"] {\r\n    .arrow::before { display: none; }\r\n  }\r\n}\r\n\r\n// colored body popover\r\n.popover-primary { @include popover-full-color($az-color-primary); }\r\n.popover-secondary { @include popover-full-color($az-color-secondary); }\r\n","/* ###### 3.13 Progress ###### */\r\n\r\n.progress { height: auto; }\r\n\r\n.progress,\r\n.progress-bar {\r\n  border-radius: 0;\r\n}\r\n\r\n.progress-bar {\r\n  height: 10px;\r\n  font-size: 11px;\r\n}\r\n\r\n.progress-bar-xs  { height: 5px;  }\r\n.progress-bar-sm { height: 8px; }\r\n.progress-bar-lg { height: 15px; }\r\n","/* ###### 3.14 Table ###### */\r\n\r\n.table {\r\n  color: $gray-800;\r\n\r\n  thead th,\r\n  thead td {\r\n    color: $gray-600;\r\n    font-weight: 700;\r\n    font-size: 11px;\r\n    letter-spacing: .5px;\r\n    text-transform: uppercase;\r\n    border-bottom-width: 1px;\r\n    border-top-width: 0;\r\n    padding: 0 15px 5px;\r\n  }\r\n\r\n  tbody tr {\r\n    background-color: rgba(#fff, .5);\r\n    th { font-weight: 500; }\r\n  }\r\n\r\n  th,\r\n  td {\r\n    padding: 9px 15px;\r\n    line-height: 1.462;\r\n  }\r\n}\r\n\r\n.table-striped {\r\n  tbody tr:nth-of-type(2n+1) { background-color: rgba($gray-500, .1); }\r\n}\r\n\r\n.table-bordered {\r\n  thead th,\r\n  thead td {\r\n    border-top-width: 1px;\r\n    padding-top: 7px;\r\n    padding-bottom: 7px;\r\n    background-color: rgba(#fff, .5);\r\n  }\r\n}\r\n","/* ###### 3.15 Tooltip ###### */\r\n\r\n.tooltip { top: 0; }\r\n\r\n.tooltip-inner {\r\n  font-size: 12px;\r\n  @include border-radius(2px);\r\n}\r\n\r\n.tooltip-primary { @include tooltip-variant($az-color-primary); }\r\n.tooltip-secondary { @include tooltip-variant($az-color-secondary); }\r\n","/* ###### 4.1 Datatables ###### */\r\n\r\ntable.dataTable {\r\n  border: 1px solid $gray-300;\r\n  margin-bottom: 15px;\r\n\r\n  thead {\r\n    th, td {\r\n      padding: 0.75rem;\r\n      border-bottom: 1px solid $gray-300;\r\n      position: relative;\r\n\r\n      &.sorting,\r\n      &.sorting_asc,\r\n      &.sorting_desc {\r\n        background-image: none;\r\n\r\n        &::after {\r\n          content: '';\r\n          border: 4px solid transparent;\r\n          border-top-color: $gray-400;\r\n          position: absolute;\r\n          z-index: 10;\r\n          top: 22px;\r\n          right: 8px;\r\n        }\r\n\r\n        &::before {\r\n          content: '';\r\n          border: 4px solid transparent;\r\n          border-bottom-color: $gray-400;\r\n          position: absolute;\r\n          z-index: 10;\r\n          top: 12px;\r\n          right: 8px;\r\n        }\r\n      }\r\n\r\n      &.sorting_asc::before { border-bottom-color: $gray-800; }\r\n      &.sorting_desc::after { border-top-color: $gray-800; }\r\n    }\r\n  }\r\n\r\n  tbody {\r\n    th, td { padding: 0.75rem; }\r\n  }\r\n\r\n  &.row-border,\r\n  &.display {\r\n    tbody {\r\n      th, td { border-top-color: $gray-300; }\r\n    }\r\n  }\r\n\r\n  &.no-footer { border-bottom-color: $gray-300; }\r\n}\r\n\r\n// Number of page filtering wrapper found at top left of datatable\r\n.dataTables_length {\r\n  padding-bottom: 10px;\r\n\r\n  .select2-container {\r\n    width: 60px;\r\n    margin-left: 0;\r\n    margin-right: 10px;\r\n  }\r\n}\r\n\r\n// Search wrapper found at top right of datatable\r\n.dataTables_filter {\r\n  padding-bottom: 10px;\r\n  padding-right: 5px;\r\n\r\n  input {\r\n    @extend .form-control;\r\n  }\r\n}\r\n\r\n// Pagination\r\n.dataTables_wrapper {\r\n  .dataTables_info {\r\n    height: 40px;\r\n    display: flex;\r\n    align-items: center;\r\n    padding-top: 0;\r\n  }\r\n\r\n  .dataTables_paginate {\r\n    padding-top: 0;\r\n\r\n    .paginate_button {\r\n      padding-top: 0.54rem;\r\n      padding-bottom: 0.54rem;\r\n      background-color: $gray-200;\r\n      border-color: transparent;\r\n      border-radius: 0;\r\n      line-height: 1.481;\r\n\r\n      &:hover,\r\n      &:focus {\r\n        background-color: $gray-400;\r\n        background-image: none;\r\n        border-color: transparent;\r\n        color: $gray-800 !important;\r\n      }\r\n\r\n      &:active { box-shadow: none; }\r\n\r\n      &.current {\r\n        &,&:hover,&:focus {\r\n          background-color: theme-color('primary');\r\n          background-image: none;\r\n          border-color: transparent;\r\n          color: #fff !important;\r\n        }\r\n      }\r\n\r\n      &.disabled {\r\n        &,&:hover,&:focus {\r\n          background-color: $gray-200;\r\n          color: $gray-500 !important;\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n","/* ###### 3.2 Datepicker ###### */\r\n\r\n.ui-datepicker {\r\n  background-color: #fff;\r\n  border: 1px solid $az-border-color;\r\n  font-family: inherit;\r\n  font-size: inherit;\r\n  padding: 10px;\r\n  margin: 1px 0 0;\r\n  display: none;\r\n  width: auto !important;\r\n  z-index: 5