\n\r\n      > li {\r\n        flex: 1;\r\n        width: auto;\r\n        float: none;\r\n      }\r\n    }\r\n  }\r\n  > .content {}\r\n  > .actions {}\r\n}\r\n\r\n/****** EQUAL COLUMN WIDTH STEP INDICATOR *****/\r\n.step-equal-width {\r\n  > .steps {\r\n    > ul {\r\n      display: flex;\r\n\r\n      > li {\r\n        flex: 1;\r\n        width: auto;\r\n        float: none;\r\n      }\r\n    }\r\n  }\r\n  > .content {}\r\n  > .actions {}\r\n}\r\n\r\n/***** CUSTOM STYLES *****/\r\n.wizard-style-1 {\r\n  > .steps {\r\n    > ul {\r\n      a,a:hover,a:active {\r\n        padding: 0;\r\n        height: 50px;\r\n\r\n        .number {\r\n          width: 50px;\r\n          height: 100%;\r\n          border: 0;\r\n          font-size: 18px;\r\n          font-weight: bold;\r\n          color: $gray-600;\r\n          background-color: $gray-300;\r\n          @include border-radius(0);\r\n        }\r\n\r\n        .title {\r\n          margin-right: 20px;\r\n          margin-left: 20px;\r\n        }\r\n      }\r\n\r\n      .current a {\r\n        &,&:hover,&:active {\r\n          .number {\r\n            background-color: darken($az-color-primary, 5%);\r\n            color: #fff;\r\n          }\r\n        }\r\n      }\r\n\r\n      .done a {\r\n        &,&:hover,&:active {\r\n          .number {\r\n            background-color: darken($purple, 5%);\r\n            color: #fff;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.wizard-style-2 {\r\n  > .steps {\r\n    > ul {\r\n      a,a:hover,a:active {\r\n        padding: 0;\r\n        height: 50px;\r\n        @include border-radius(50px);\r\n\r\n        .number {\r\n          width: 50px;\r\n          height: 100%;\r\n          border: 2px solid $gray-200;\r\n          font-size: 18px;\r\n          font-weight: bold;\r\n          color: $gray-600;\r\n          background-color: #fff;\r\n        }\r\n\r\n        .title { margin-right: 20px; }\r\n      }\r\n\r\n      .current a {\r\n        &,&:hover,&:active {\r\n          .number {\r\n            border-color: $az-color-primary;\r\n            color: $az-color-primary;\r\n          }\r\n        }\r\n      }\r\n\r\n      .done a {\r\n        &,&:hover,&:active {\r\n          .number {\r\n            border-color: $purple;\r\n            color: $purple;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n","/* ###### 4.5 Morris ###### */\r\n.morris-hover.morris-default-style { border-radius: 0; }\r\n","\r\n/* ###### 4.6 Parsley ###### */\r\n\r\ninput.parsley-error,\r\ntextarea.parsley-error {\r\n  @extend .is-invalid;\r\n\r\n  &:focus { box-shadow: none !important; }\r\n}\r\n\r\ninput.parsley-success,\r\ntextarea.parsley-success {\r\n  @extend .is-valid;\r\n  &:focus { box-shadow: none !important; }\r\n}\r\n\r\n.parsley-checkbox {\r\n  &.parsley-error {\r\n    display: inline-block;\r\n    padding: 10px;\r\n    border: 1px solid theme-color('danger');\r\n  }\r\n\r\n  &.parsley-success {\r\n    display: inline-block;\r\n    padding: 10px;\r\n    border: 1px solid theme-color('success');\r\n  }\r\n}\r\n\r\n.parsley-select {\r\n  &.parsley-error {\r\n    @extend .has-danger;\r\n  }\r\n\r\n  &.parsley-success {\r\n    @extend .has-success;\r\n  }\r\n}\r\n\r\n\r\n.parsley-errors-list {\r\n  color: theme-color('danger');\r\n  list-style: none;\r\n  font-size: 12px;\r\n  padding: 0;\r\n  margin-bottom: 0;\r\n\r\n  li { margin: 5px 0 0; }\r\n}\r\n\r\n/***** CUSTOM STYLED ERROR MESSAGE *****/\r\n.parsley-style-1 {\r\n  .parsley-input {\r\n    &.parsley-error {\r\n      .form-control {\r\n        background-color: lighten(theme-color('danger'), 45%);\r\n        border-color: theme-color('danger');\r\n        border-bottom-width: 0;\r\n        @include border-bottom-radius(0);\r\n      }\r\n    }\r\n\r\n    &.parsley-success {\r\n      .form-control { border-color: theme-color('success'); }\r\n    }\r\n  }\r\n\r\n  .parsley-checkbox {\r\n    &.parsley-error {\r\n      border: 1px solid theme-color('danger');\r\n      background-color: lighten(theme-color('danger'), 45%);\r\n      @include border-top-radius(2px);\r\n    }\r\n  }\r\n\r\n  .parsley-select {\r\n    &.parsley-error {\r\n      .select2-container--default .select2-selection--single {\r\n        background-color: lighten(theme-color('danger'), 45%);\r\n        @include border-bottom-radius(0);\r\n      }\r\n    }\r\n  }\r\n\r\n  .parsley-errors-list.filled {\r\n    background-color: theme-color('danger');\r\n    color: #fff;\r\n    padding: 7px 10px;\r\n    @include border-bottom-radius(2px);\r\n\r\n    li:first-child { margin-top: 0; }\r\n  }\r\n}\r\n","/* ###### 4.4 jQVMap ###### */\r\n\r\n.jqvmap-label {\r\n  padding: 2px 8px;\r\n  background-color: rgba(#111, 0.9);\r\n  @include border-radius(2px);\r\n}\r\n\r\n.jqvmap-zoomin,\r\n.jqvmap-zoomout {\r\n  font-size: 20px;\r\n  padding: 0;\r\n  width: 20px;\r\n  height: 20px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  @include border-radius(2px);\r\n}\r\n\r\n.jqvmap-zoomout { top: 32px; }\r\n\r\n/* Setup basic CSS for Label */\r\n.jqvmap-pin {\r\n  font-family: $font-family-base;\r\n  cursor: default;\r\n  pointer-events: none;\r\n}\r\n\r\n/* Hide Whichever Labels you want */\r\n#jqvmap1_ri_pin, #jqvmap1_dc_pin, #jqvmap1_de_pin, #jqvmap1_md_pin {\r\n  display: none;\r\n}\r\n\r\n/* Reposition Labels that are not quite right ( labels are centered in shape, and sometimes need tweaking ) */\r\n\r\n#jqvmap1_ak_pin { margin-top: -2%; }\r\n#jqvmap1_ca_pin { margin-left: -2%; }\r\n#jqvmap1_ct_pin {\r\n  margin-top: -0.25%;\r\n  margin-left: -0.25%;\r\n}\r\n#jqvmap1_fl_pin { margin-left: 5%; }\r\n#jqvmap1_id_pin {\r\n  margin-top: 3%;\r\n  margin-left: -1%;\r\n}\r\n#jqvmap1_ky_pin { margin-left: 2%; }\r\n#jqvmap1_la_pin { margin-left: -2%; }\r\n#jqvmap1_mi_pin {\r\n  margin-top: 4%;\r\n  margin-left: 3%;\r\n}\r\n#jqvmap1_ma_pin { margin-top: -0.25%; }\r\n#jqvmap1_mn_pin {\r\n  margin-top: 2%;\r\n  margin-left: -2%;\r\n}\r\n#jqvmap1_nh_pin {\r\n  margin-top: 1%;\r\n  margin-left: -0.25%;\r\n}\r\n#jqvmap1_nj_pin { margin-top: 1%; }\r\n#jqvmap1_ok_pin { margin-left: 2%; }\r\n#jqvmap1_va_pin { margin-left: 2%; }\r\n#jqvmap1_wv_pin {\r\n  margin-left: -1%;\r\n  margin-top: 1%;\r\n}\r\n\r\n/* Add responsibe support to resize labels for difference screen sizes */\r\n\r\n@media only screen and (min-width: 320px) {\r\n  .jqvmap-pin { font-size: 6px; }\r\n}\r\n\r\n@media only screen and (min-width: 480px) {\r\n  .jqvmap-pin { font-size: 8px; }\r\n}\r\n\r\n@media only screen and (min-width: 640px) {\r\n  .jqvmap-pin { font-size: 10px; }\r\n}\r\n\r\n@media only screen and (min-width: 800px) {\r\n  .jqvmap-pin { font-size: 12px; }\r\n}\r\n\r\n@media only screen and (min-width: 1024px) {\r\n  .jqvmap-pin { font-size: 14px; }\r\n}\r\n","/* ###### 4.7 Quill ###### */\r\n\r\n.ql-wrapper {\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.ql-wrapper-modal {\r\n  .ql-snow {\r\n    &.ql-toolbar {\r\n      border-width: 0;\r\n      border-bottom-width: 1px;\r\n\r\n      @include media-breakpoint-up(sm) { padding: 15px 20px; }\r\n    }\r\n\r\n    &.ql-container { border-width: 0; }\r\n\r\n    .ql-editor { padding: 20px; }\r\n  }\r\n}\r\n\r\n.ql-bubble {\r\n  &.ql-container {\r\n    border: 2px solid $gray-200;\r\n\r\n    &:not(.ql-disabled) a::before {\r\n      background-color: $gray-900;\r\n      border-radius: 2px;\r\n    }\r\n  }\r\n\r\n  .ql-tooltip {\r\n    background-color: $gray-900;\r\n    border-radius: 2px;\r\n\r\n    &.ql-flip .ql-tooltip-arrow { border-top-color: $gray-900; }\r\n    &:not(.ql-flip) .ql-tooltip-arrow { border-bottom-color: $gray-900; }\r\n  }\r\n\r\n  .ql-toolbar {\r\n    padding: 0 8px 8px;\r\n\r\n    button {\r\n      width: 32px;\r\n      height: 32px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      color: darken($gray-500, 5%);\r\n      outline: none;\r\n\r\n      i {\r\n        font-size: 24px;\r\n        line-height: 0;\r\n        display: inline-block;\r\n\r\n        &.la-bold,\r\n        &.la-underline { width: 21px; }\r\n      }\r\n\r\n      .ql-fill { fill: darken($gray-500, 5%); }\r\n      .ql-stroke { stroke: darken($gray-500, 5%); }\r\n\r\n      &.ql-active {\r\n        color: #fff;\r\n        background-color: rgba(#fff, .08);\r\n      }\r\n    }\r\n\r\n    .ql-formats {\r\n      margin: 8px 8px 0 0;\r\n      &:first-child { margin-left: 0; }\r\n\r\n      @include media-breakpoint-up(sm) {\r\n        margin: 8px 0 0;\r\n        &:first-child { margin-left: 0; }\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n\r\n.ql-snow {\r\n  &.ql-container {\r\n    border-color: $gray-200;\r\n    border-width: 2px;\r\n  }\r\n\r\n  &.ql-toolbar {\r\n    border-width: 2px;\r\n    border-color: $gray-200;\r\n    border-bottom-width: 1px;\r\n    padding: 5px 10px 10px;\r\n\r\n    @include media-breakpoint-up(sm) { padding: 15px; }\r\n\r\n    .ql-picker-label {\r\n      border-color: $gray-400;\r\n\r\n      &.ql-active {\r\n        background-color: $gray-200;\r\n        border-color: transparent;\r\n        color: $gray-900;\r\n        font-weight: 500;\r\n\r\n        .ql-stroke { stroke: $body-color; }\r\n      }\r\n    }\r\n\r\n    button {\r\n      border: 1px solid transparent;\r\n      width: 32px;\r\n      height: 32px;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      color: $body-color;\r\n      outline: none;\r\n\r\n      svg {\r\n        width: 20px;\r\n        float: none;\r\n      }\r\n\r\n      i {\r\n        font-size: 24px;\r\n        line-height: 0;\r\n        display: inline-block;\r\n\r\n        &.la-bold,\r\n        &.la-underline { width: 21px; }\r\n      }\r\n\r\n      .ql-stroke { stroke-width: 2px; }\r\n\r\n      @include hover-focus() {\r\n        border-color: $gray-400;\r\n        color: lighten($body-color, 15%);\r\n\r\n        .ql-stroke { stroke: $gray-600; }\r\n      }\r\n\r\n      &.ql-active {\r\n        background-color: $gray-200;\r\n        color: $gray-800;\r\n        border-color: transparent;\r\n\r\n        .ql-fill { fill: $gray-800; }\r\n        .ql-stroke { stroke: $gray-800; }\r\n      }\r\n    }\r\n\r\n    .ql-formats {\r\n      margin-top: 5px;\r\n      margin-right: 5px;\r\n    }\r\n  }\r\n\r\n  .ql-formats {\r\n    button + button { margin: 0 0 0 2px; }\r\n  }\r\n\r\n  .ql-picker {\r\n    display: block;\r\n    border-width: 0;\r\n    height: 32px;\r\n    color: $gray-700;\r\n\r\n    &:not(.ql-color-picker):not(.ql-icon-picker) svg { right: 3px; }\r\n\r\n    @include hover-focus() {\r\n      .ql-picker-label {\r\n        color: $gray-900;\r\n        .ql-stroke { stroke: $body-color; }\r\n      }\r\n    }\r\n\r\n    &.ql-header { width: 120px; }\r\n  }\r\n\r\n  .ql-picker-label {\r\n    display: block;\r\n    padding-left: 10px;\r\n    font-size: $font-size-sm;\r\n    font-family: $font-family-base;\r\n    border: 1px solid $gray-300;\r\n    background-color: #fff;\r\n    outline: none;\r\n\r\n    &::before {\r\n      line-height: 2.25;\r\n      font-weight: 400;\r\n    }\r\n  }\r\n\r\n  .ql-stroke {\r\n    stroke: $body-color;\r\n    stroke-linecap: square;\r\n    stroke-linejoin: miter;\r\n    stroke-width: 1;\r\n  }\r\n\r\n  .ql-editor {\r\n    padding: 20px;\r\n    color: $gray-800;\r\n  }\r\n}\r\n","\r\n/* ###### 4.8 RangeSlider ###### */\r\n.irs-min, .irs-max {\r\n  font-family: $font-family-roboto;\r\n  @include border-radius(0);\r\n}\r\n\r\n.irs-from, .irs-to, .irs-single {\r\n  font-family: $font-family-roboto;\r\n  background-color: $az-color-primary;\r\n  @include border-radius(0);\r\n}\r\n\r\n.irs-bar {\r\n  background-image: none;\r\n  background-color: $az-color-primary;\r\n}\r\n\r\n.irs-bar-edge {\r\n  background-image: none;\r\n  background-color: $az-color-primary;\r\n  @include border-left-radius(0);\r\n}\r\n\r\n.irs-line-left {\r\n  background-image: none;\r\n  background-color: $gray-300;\r\n  @include border-left-radius(0);\r\n}\r\n\r\n.irs-line-mid {\r\n  background-image: none;\r\n  background-color: $gray-300;\r\n}\r\n\r\n.irs-line-right {\r\n  background-image: none;\r\n  background-color: $gray-300;\r\n  @include border-right-radius(0);\r\n}\r\n\r\n.irs-from::after, .irs-to::after,\r\n.irs-single::after {\r\n\tborder-top-color: $az-color-primary;\r\n}\r\n\r\n.irs-slider {\r\n  background-image: none;\r\n\r\n  &:before {\r\n    content: '';\r\n    width: 2px;\r\n    height: 18px;\r\n    position: absolute;\r\n    background-color: $az-color-primary;\r\n    left: 50%;\r\n    margin-left: -1px;\r\n  }\r\n\r\n  &:hover,\r\n  &:focus {\r\n    &:before { background-color: darken($az-color-primary, 12%); }\r\n  }\r\n}\r\n\r\n\r\n/* #################### COLOR VARIANT SKINS #################### */\r\n\r\n.irs-primary { @include irs-color-variant($blue); }\r\n.irs-success { @include irs-color-variant($green); }\r\n.irs-dark    { @include irs-color-variant($gray-800); }\r\n\r\n\r\n/* #################### MODERN SKIN #################### */\r\n\r\n.irs-modern {\r\n  .irs-line-left,\r\n  .irs-line-mid,\r\n  .irs-line-right {\r\n    height: 6px;\r\n    box-shadow: inset -2px 2px 2px 0 rgba(#222, 0.1);\r\n  }\r\n\r\n  .irs-bar,\r\n  .irs-bar-edge {\r\n    height: 6px;\r\n    box-shadow: inset 0 1px 1px 0 rgba(#222, 0.1);\r\n  }\r\n\r\n  .irs-slider {\r\n    top: 19px;\r\n    background-color: #fff;\r\n    border: 1px solid $az-color-primary;\r\n    @include border-radius(0);\r\n\r\n    &::before {\r\n      width: 4px;\r\n      height: 9px;\r\n      background-color: #fff;\r\n      border-left: 1px solid $az-color-primary;\r\n      border-right: 1px solid $az-color-primary;\r\n      margin-left: -2px;\r\n      top: 3px;\r\n    }\r\n  }\r\n\r\n  &.irs-primary { @include irs-modern-slider-variant($blue); }\r\n  &.irs-success { @include irs-modern-slider-variant($green); }\r\n  &.irs-dark { @include irs-modern-slider-variant($gray-900); }\r\n\r\n}\r\n\r\n\r\n/* #################### OUTLINE SKIN #################### */\r\n.irs-outline {\r\n  .irs-line {\r\n    border: 1px solid $az-color-primary;\r\n    height: 10px;\r\n    @include border-radius(5px);\r\n  }\r\n\r\n  .irs-line-left,\r\n  .irs-line-mid,\r\n  .irs-line-right {\r\n    height: 10px;\r\n    background-color: transparent;\r\n  }\r\n\r\n  .irs-bar,\r\n  .irs-bar-edge { height: 10px; }\r\n\r\n  .irs-bar-edge { @include border-left-radius(5px); }\r\n\r\n  .irs-slider {\r\n    top: 21px;\r\n    width: 18px;\r\n    background-color: #fff;\r\n    border: 1px solid $az-color-primary;\r\n    @include border-radius(100%);\r\n\r\n    &::before {\r\n      margin-left: -4px;\r\n      top: 4px;\r\n      width: 8px;\r\n      height: 8px;\r\n      @include border-radius(100%);\r\n    }\r\n\r\n    &:hover,\r\n    &:focus {\r\n      &::before { background-color: darken($az-color-primary, 5%); }\r\n    }\r\n  }\r\n\r\n  &.irs-primary { @include irs-outline-variant($blue); }\r\n  &.irs-success { @include irs-outline-variant($green); }\r\n  &.irs-dark { @include irs-outline-variant($gray-800); }\r\n}\r\n","\r\n// Ion Rangeslider Skins\r\n@mixin irs-color-variant($color) {\r\n  .irs-bar,\r\n  .irs-bar-edge,\r\n  .irs-slider::before { background-color: $color; }\r\n\r\n  .irs-from,\r\n  .irs-to,\r\n  .irs-single {\r\n    background-color: $color;\r\n    &::after { border-top-color: $color; }\r\n  }\r\n}\r\n\r\n@mixin irs-modern-slider-variant($color) {\r\n  .irs-slider {\r\n    border-color: $color;\r\n    &::before { border-color: $color; }\r\n  }\r\n}\r\n\r\n@mixin irs-outline-variant($color) {\r\n  .irs-line,\r\n  .irs-slider {\r\n    border-color: $color;\r\n    &:hover,\r\n    &:focus {\r\n      &::before { background-color: darken($color, 5%); }\r\n    }\r\n  }\r\n}\r\n\r\n\r\n// $name = class name\r\n// $perc = donut percentage value\r\n// $size = size of donut\r\n// $width = width of chart\r\n// $base = thickness of donut\r\n// $center = background color of the percentage\r\n// $color = background color of donut hole\r\n// $textColor = color of text in center and the percentage\r\n// $textSize = size of text\r\n@mixin donut-chart($name, $perc, $size, $width, $base, $center, $color, $textColor: $color, $textSize: 40px) {\r\n\r\n  $color2: $color;\r\n  $base2: $base;\r\n\t$deg: ($perc/100*360)+deg;\r\n\t$deg1: 90deg;\r\n\t$deg2: $deg;\r\n\r\n\t// If percentage is less than 50%\r\n\t@if $perc < 50 {\r\n\t\t$base: $color;\r\n    $color: $base2;\r\n    $color2: $base2;\r\n    $deg1: ($perc/100*360+90)+deg;\r\n\t\t$deg2: 0deg;\r\n\t}\r\n\r\n  .az-donut-chart {\r\n    &#{$name} {\r\n      width: $size;\r\n      height: $size;\r\n      background: $base;\r\n\r\n      .slice {\r\n        &.one {\r\n          clip: rect(0 $size $size/2 0);\r\n          -webkit-transform: rotate($deg1);\r\n          transform: rotate($deg1);\r\n          background: $color;\r\n        }\r\n\r\n        &.two {\r\n          clip: rect(0 $size/2 $size 0);\r\n          -webkit-transform: rotate($deg2);\r\n          transform: rotate($deg2);\r\n          background: $color2;\r\n        }\r\n      }\r\n\r\n      .chart-center {\r\n        top: $width;\r\n        left: $width;\r\n        width: $size - ($width * 2);\r\n        height: $size - ($width * 2);\r\n        background: $center;\r\n\r\n        span {\r\n          font-size: $textSize;\r\n          line-height: $size - ($width * 2);\r\n          color: $textColor;\r\n\r\n          &:after {\r\n          content: '#{$perc}%';\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n","/* ###### 4.9 Perfect Scrollbar ###### */\r\n\r\n.ps {\r\n  overflow: hidden;\r\n\r\n  > .ps__rail-y {\r\n    width: 5px;\r\n    background-color: rgba($gray-900, .04);\r\n    z-index: 10;\r\n    position: absolute;\r\n    left: auto !important;\r\n    right: 0;\r\n    opacity: 0;\r\n    @include transition(opacity .2s);\r\n\r\n    > .ps__thumb-y {\r\n      position: absolute;\r\n      @include border-radius(0);\r\n      width: 2px;\r\n      left: 2px;\r\n      background-color: $gray-500;\r\n    }\r\n  }\r\n\r\n  &.ps--active-y {\r\n    &:hover,\r\n    &:focus {\r\n      > .ps__rail-y { opacity: 1; }\r\n    }\r\n  }\r\n}\r\n","/* ###### 4.10 Select2 ###### */\r\n\r\n.select2-results__option {\r\n  border-radius: 0;\r\n  margin-bottom: 1px;\r\n  font-size: $font-size-sm;\r\n}\r\n\r\n.select2-container--default {\r\n\r\n  .select2-selection--single {\r\n    background-color: #fff;\r\n    border-color: $input-border-color;\r\n    @include border-radius();\r\n    height: $az-height-base; //$input-height;\r\n    outline: none;\r\n    border-radius: 0;\r\n\r\n    .select2-selection__rendered {\r\n      color: $input-color;\r\n      line-height: $input-height - .1rem;\r\n      padding-left: $input-btn-padding-x;\r\n      height: 100%;\r\n      display: flex;\r\n      align-items: center;\r\n    }\r\n\r\n    .select2-selection__placeholder {\r\n      color: $input-placeholder-color;\r\n    }\r\n\r\n    .select2-selection__arrow {\r\n      width: 30px;\r\n      height: $az-height-base; //$input-height;\r\n      line-height: $input-height;\r\n\r\n      b { margin-top: -3px; }\r\n    }\r\n  }\r\n\r\n  .select2-selection--multiple {\r\n    background-color: $input-bg;\r\n    border-color: $input-border-color;\r\n    border-radius: 0;\r\n    min-height: $az-height-base; //$input-height;\r\n    outline: none;\r\n\r\n    .select2-selection__rendered {\r\n      padding: 0 4px;\r\n    }\r\n\r\n    .select2-selection__choice {\r\n      position: relative;\r\n      margin-top: 5px;\r\n      margin-right: 4px;\r\n      padding: 3px 10px 3px 20px;\r\n      border-color: transparent;\r\n      border-radius: 0; //2px;\r\n      background-color: $az-color-primary;\r\n      color: #fff;\r\n      line-height: 1.45;\r\n    }\r\n\r\n    .select2-selection__choice__remove {\r\n      color: #fff;\r\n      opacity: .5;\r\n      font-size: 12px;\r\n      display: inline-block;\r\n      position: absolute;\r\n      top: 4px;\r\n      left: 7px;\r\n    }\r\n  }\r\n\r\n  &.select2-container--focus .select2-selection--multiple {\r\n    border-color: $input-border-color;\r\n  }\r\n\r\n  .select2-search--dropdown .select2-search__field {\r\n    border-color: $input-border-color;\r\n    border-radius: 0; //$border-radius;\r\n  }\r\n\r\n  .select2-results__option[aria-selected=\"true\"] {\r\n    background-color: lighten($body-bg, 5%);\r\n  }\r\n\r\n  .select2-results__option--highlighted[aria-selected] {\r\n    background-color: $az-color-primary;\r\n  }\r\n\r\n  .select2-results > .select2-results__options {\r\n    margin: 4px;\r\n  }\r\n\r\n  .select2-search--inline .select2-search__field {\r\n    margin-top: 7px;\r\n    line-height: 26px;\r\n    padding-left: 7px;\r\n    opacity: 1;\r\n  }\r\n\r\n  &.select2-container--disabled {\r\n    .select2-selection__choice {\r\n      padding-left: 10px;\r\n      background-color: $gray-500;\r\n\r\n      .select2-selection__choice__remove { display: none; }\r\n    }\r\n\r\n  }\r\n}\r\n\r\n.select2-container--open {\r\n\r\n  .select2-selection--single,\r\n  .select2-selection--multiple {\r\n    background-color: #fff;\r\n    border-color: $input-border-color;\r\n  }\r\n\r\n  .select2-dropdown--above {\r\n    @include border-top-radius(0);\r\n  }\r\n\r\n  .select2-dropdown--below {\r\n    @include border-bottom-radius(0);\r\n    top: 0; //$input-height - 1.15;\r\n  }\r\n}\r\n\r\n.select2-dropdown {\r\n  border-color: $input-border-color;\r\n  z-index: 200;\r\n}\r\n\r\n.select2-search--dropdown {\r\n  padding-bottom: 0;\r\n}\r\n\r\n.select2-results__option {\r\n  padding: 6px 10px;\r\n  font-size: $font-size-base;\r\n}\r\n\r\n\r\n// Alert State\r\n.has-success .select2-container--default .select2-selection--single { border-color: theme-color('success'); }\r\n.has-warning .select2-container--default .select2-selection--single { border-color: theme-color('warning'); }\r\n.has-danger .select2-container--default .select2-selection--single { border-color: theme-color('danger'); }\r\n\r\n\r\n// Size\r\n.select2-xs + .select2-container { font-size: 12px; }\r\n.select2-dropdown-xs .select2-results__option {  font-size: 12px; }\r\n\r\n.select2-sm + .select2-container { font-size: 14px; }\r\n.select2-dropdown-sm .select2-results__option {  font-size: 14px; }\r\n\r\n// Border\r\n.select2-bd-0 + .select2-container--default .select2-selection--single { border-width: 0; }\r\n.bg-gray + .select2-container--default .select2-selection--single {\r\n  background-color: lighten($gray-800, 5%);\r\n  .select2-selection__rendered { color: $gray-300; }\r\n}\r\n","/* ###### 4.11 Spectrum ###### */\r\n\r\n.sp-container {\r\n  background-color: #fff;\r\n  border-color: $gray-500;\r\n  //box-shadow: 0px 1px 3px 0px rgba(#000, 0.21);\r\n  z-index: 200;\r\n\r\n  button {\r\n    @extend .btn;\r\n    border: 0;\r\n    padding: 8px 15px;\r\n    background-image: none;\r\n    background-color: $gray-400;\r\n    font-family: $font-family-base;\r\n    font-size: 12px;\r\n    text-shadow: none;\r\n    text-transform: capitalize;\r\n    @include border-radius(2px);\r\n\r\n    &:hover,\r\n    &:focus {\r\n      border: 0;\r\n      background-image: none;\r\n      background-color: $gray-500;\r\n      text-shadow: none;\r\n    }\r\n  }\r\n}\r\n\r\n.sp-button-container .sp-cancel {\r\n  font-family: $font-family-base;\r\n  font-size: 12px;\r\n  text-transform: capitalize;\r\n  color: $gray-600 !important;\r\n\r\n  &:hover,\r\n  &:focus {\r\n    color: $gray-800 !important;\r\n    text-decoration: none;\r\n  }\r\n}\r\n\r\n.sp-picker-container {\r\n  border-left: 0;\r\n}\r\n\r\n.sp-replacer {\r\n  border-color: $gray-500;\r\n  background-color: #fff;\r\n\r\n  &:hover,\r\n  &:focus {\r\n    border-color: $gray-600;\r\n  }\r\n\r\n  &.sp-active { border-color: $gray-600; }\r\n}\r\n\r\n.sp-dd {\r\n  text-indent: -99999px;\r\n  position: relative;\r\n  width: 10px;\r\n\r\n  &::before {\r\n    content: '\\f280';\r\n    font-family: 'Ionicons';\r\n    font-size: 15px;\r\n    color: $gray-500;\r\n    position: absolute;\r\n    text-indent: 0;\r\n    left: 0;\r\n    z-index: 10;\r\n  }\r\n}\r\n\r\n.sp-preview { border: 0; }\r\n.sp-dragger { background-color: transparent; }\r\n\r\n.sp-choose {\r\n  background-color: $gray-300;\r\n}\r\n\r\n.sp-palette {\r\n  .sp-thumb-el:hover,\r\n  .sp-thumb-el.sp-thumb-active {\r\n    border-color: $gray-800;\r\n  }\r\n}\r\n","/* ###### 5.1 Buttons  ###### */\r\n\r\n.btn-az-primary { @include button-variant($indigo, darken($indigo, 5%)); }\r\n.btn-az-secondary { @include button-variant($blue, darken($blue, 5%)); }\r\n\r\n.btn-rounded {\r\n  @include border-radius(50px);\r\n}\r\n\r\n.btn-with-icon {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  height: $az-height-base;\r\n\r\n  i {\r\n    line-height: 0;\r\n    font-size: 20px;\r\n    margin-right: 5px;\r\n\r\n    &.typcn { line-height: .9; }\r\n    &.fas { font-size: 15px; }\r\n    &.icon { font-size: 18px; }\r\n  }\r\n}\r\n\r\n.btn-icon {\r\n  width: $az-height-base;\r\n  height: $az-height-base;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n\r\n  i {\r\n    line-height: 0;\r\n    font-size: 24px;\r\n\r\n    &.typcn { line-height: .8; }\r\n  }\r\n}\r\n","/* ###### 5.2 Charts  ###### */\r\n\r\n.az-donut-chart {\r\n  position: relative;\r\n  border-radius: 50%;\r\n  overflow: hidden;\r\n\r\n  .slice {\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n  }\r\n\r\n  .chart-center {\r\n    position: absolute;\r\n    border-radius: 50%;\r\n\r\n    span {\r\n      display: block;\r\n      text-align: center;\r\n    }\r\n  }\r\n}\r\n","/* ###### 5.3 Forms   ###### */\r\n\r\n/* Checkbox */\r\n.ckbox {\r\n  font-weight: normal;\r\n  position: relative;\r\n  display: block;\r\n  line-height: 1;\r\n  margin-bottom: 0;\r\n\r\n  span {\r\n    padding-left: 15px;\r\n\r\n    &:empty { float: left; }\r\n\r\n    &:before,\r\n    &:after {\r\n      line-height: 18px;\r\n      position: absolute;\r\n    }\r\n\r\n    &:before {\r\n      content: '';\r\n      width: $ckbox-size;\r\n      height: $ckbox-size;\r\n      background-color: #fff;\r\n      border: 1px solid $gray-500;\r\n      top: 1px;\r\n      left: 0;\r\n    }\r\n\r\n    &:after {\r\n      top: 1px;\r\n      left: 0;\r\n      width: $ckbox-size;\r\n      height: $ckbox-size;\r\n      content: '';\r\n      background-image: url(\"data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 8 8'%3E%3Cpath fill='%23fff' d='M6.564.75l-3.59 3.612-1.538-1.55L0 4.26 2.974 7.25 8 2.193z'/%3E%3C/svg%3E\");\r\n      background-size: 65%;\r\n      background-repeat: no-repeat;\r\n      background-position: 55% 45%;\r\n      background-color: theme-color('primary');\r\n      line-height: 17px;\r\n      display: none;\r\n    }\r\n\r\n    &:empty {\r\n      padding-left: 0;\r\n      width: 3px;\r\n    }\r\n  }\r\n\r\n  input[type='checkbox'] {\r\n    opacity: 0;\r\n    margin: 0;\r\n\r\n    &:checked {\r\n      + span:after { display: block; }\r\n    }\r\n\r\n    &[disabled] {\r\n      + span,\r\n      + span:before,\r\n      + span:after {\r\n        opacity: .75;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.ckbox-inline { display: inline-block; }\r\n\r\n/* Radio Box */\r\n.rdiobox {\r\n  font-weight: normal;\r\n  position: relative;\r\n  display: block;\r\n  line-height: 18px;\r\n\r\n  span {\r\n    padding-left: 13px;\r\n\r\n    &:before,\r\n    &:after {\r\n      line-height: 18px;\r\n      position: absolute;\r\n    }\r\n\r\n    &:before {\r\n      content: '';\r\n      width: $rdiobox-size;\r\n      height: $rdiobox-size;\r\n      background-color: #fff;\r\n      border: 1px solid $gray-500;\r\n      border-radius: 50px;\r\n      top: 2px;\r\n      left: 0;\r\n    }\r\n\r\n    &:after {\r\n      content: '';\r\n      width: $rdiobox-size - 10px;\r\n      height: $rdiobox-size - 10px;\r\n      background-color: #fff;\r\n      border-radius: 50px;\r\n      top: 7px;\r\n      left: 5px;\r\n      display: none;\r\n    }\r\n\r\n    &:empty {\r\n      padding-left: 0;\r\n      width: 16px;\r\n      display: block;\r\n    }\r\n  }\r\n\r\n  input[type='radio'] {\r\n    opacity: 0;\r\n    margin: 0;\r\n\r\n    &:checked {\r\n      + span:before {\r\n        border-color: transparent;\r\n        background-color: theme-color('primary');\r\n      }\r\n      + span:after { display: block; }\r\n    }\r\n\r\n    &[disabled] {\r\n      + span,\r\n      + span:before,\r\n      + span:after {\r\n        opacity: .75;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.rdiobox-inline { display: inline-block; }\r\n\r\n.form-group-rdiobox {\r\n  display: flex;\r\n  align-items: center;\r\n\r\n  .rdiobox {\r\n    margin-bottom: 0;\r\n\r\n    + .rdiobox { margin-left: 30px; }\r\n\r\n    span { padding-left: 0; }\r\n  }\r\n}\r\n\r\n.az-toggle {\r\n  width: 60px;\r\n  height: 25px;\r\n  background-color: $gray-400;\r\n  padding: 2px;\r\n  position: relative;\r\n  overflow: hidden;\r\n\r\n  span {\r\n    position: absolute;\r\n    top: 3px;\r\n    bottom: 3px;\r\n    left: 3px;\r\n    display: block;\r\n    width: 20px;\r\n    background-color: #fff;\r\n    cursor: pointer;\r\n    @include transition($transition-base);\r\n\r\n    &::before,\r\n    &::after {\r\n      position: absolute;\r\n      font-size: 10px;\r\n      font-weight: 500;\r\n      letter-spacing: .5px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      top: 2px;\r\n      line-height: 1.38;\r\n    }\r\n\r\n    &::before {\r\n      content: 'on';\r\n      left: -25px;\r\n    }\r\n\r\n    &::after {\r\n      content: 'off';\r\n      right: -29px;\r\n    }\r\n  }\r\n\r\n  &.on {\r\n    background-color: $az-color-primary;\r\n\r\n    span { left: 37px; }\r\n  }\r\n}\r\n\r\n.az-toggle-secondary.on { background-color: $blue; }\r\n.az-toggle-success.on { background-color: $green; }\r\n.az-toggle-dark.on { background-color: $gray-900; }\r\n\r\n\r\n.az-form-group {\r\n  padding: 12px 15px;\r\n  border: 1px solid $input-border-co